// Liquid Color — normal paint follows the production donor alpha-wave timing.
const FLOW = 2;
const SIZE = 30;
const FADE = 0;
const SPEED = 50;
const LINKS = 0;
const TERRITORY = 0;
const REBUILD_PHOTO = 1;
const PHOTO_OPACITY = 100;
const PHOTO_BLUR = 0;

function ease(a, b, value) {
  const x = Math.max(0, Math.min(1, (value - a) / (b - a)));
  return x * x * (3 - 2 * x);
}

function brush(point, stroke, t) {
  const marks = [];
  for (let i = 0; i < FLOW; i += 1) {
    const seed = point.index * 43 + i * 19 + stroke.seed * 89;
    const c = photo(point.x, point.y, PHOTO_BLUR);
    if (!c) continue;
    marks.push({
      x: point.x + (rand(seed) - .5) * SIZE * .42,
      y: point.y + (rand(seed + 7) - .5) * SIZE * .42,
      size: SIZE * (.82 + rand(seed + 13) * .58),
      alpha: .32 * PHOTO_OPACITY / 100,
      red: c.red, green: c.green, blue: c.blue,
      soft: 1
    });
  }
  return marks;
}

function move(mark, t) {
  const speed = .08 + mark.seed * .044;
  const cycle = (t * speed + mark.seed) % 1;
  const growth = ease(.005, .8, cycle);
  const appear = ease(.015, .34, cycle);
  const disappear = 1 - ease(.64, .985, cycle);
  const phase = cycle * TAU;
  return {
    dx: Math.sin(phase * .37) * 2.2,
    dy: Math.cos(phase * .29) * 1.6,
    size: .28 + growth * 1.34,
    angle: Math.sin(phase * .24) * 2.9,
    alpha: appear * disappear * .92
  };
}
